private val release050: ChangelogRelease =
    ChangelogRelease(
        version = "0.5.0",
        date = "2026-03-23",
        badge = ChangelogBadge.Stable,
        changes =
            listOf(
                ChangelogChange(
                    ChangelogChangeType.Added,
                    "**Sleep backoff for asleep vehicles** \u2014 When a vehicle returns 408 (asleep), polling now backs off " +
                        "exponentially using `WORKER_SLEEP_POLL_MULT` (default 4\u00d7): 60s \u2192 120s \u2192 240s \u2192 10 min cap. " +
                        "Previously, asleep vehicles were polled every 15s with no backoff.",
                ),
                ChangelogChange(
                    ChangelogChangeType.Added,
                    "**API Suspend Toggle** \u2014 New toggle on the Settings page to suspend ALL Tesla Fleet API calls. Useful " +
                        "when a vehicle is in service. Persisted in DB (`api_suspended` column on `settings` table, migration 000011). " +
                        "Token refresh continues during suspension so re-auth isn't needed. All API entry points are blocked: worker " +
                        "polling, CurrentState, SyncFromTesla, Wake, SendCommand.",
                ),
                ChangelogChange(
                    ChangelogChangeType.Added,
                    "**API Usage Dashboard fix** \u2014 `APIUsageHandler` now queries `api_call_logs` table for real monthly " +
                        "request counts, skipped polls (408/504), and estimated cost vs Tesla's \$10/month credit. Previously returned " +
                        "hardcoded zeros.",
                ),
                ChangelogChange(
                    ChangelogChangeType.Changed,
                    "**Single-route ingress** \u2014 All traffic now routes through a single Traefik IngressRoute (or standard " +
                        "Ingress) pointing to `teslasync-web` (Nginx). Nginx serves static files AND proxies `/api/`, `/.well-known/`, " +
                        "`/healthz`, `/readyz`, `/metrics` to `teslasync-api` over the internal Kubernetes cluster network. API traffic " +
                        "no longer traverses the ingress controller \u2014 only the initial page load does.",
