                ChangelogChange(
                    ChangelogChangeType.Changed,
                    "**New config fields** \u2014 `config.apiEndpoint` (configures Nginx proxy_pass target and frontend API base " +
                        "URL via `sub_filter`), `config.webEndpoint` (public URL for CORS)",
